import{Module}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{THREE,materials}from'./geometry.js';import data from'./geometry-data.js';import{spec}from'./dimensions.js';
function build(host,sourceRole,shape){const frame=new THREE.Group();frame.name='TimerCamera-X own static '+shape+' source mating frame';frame.rotation.x=Math.PI/2;frame.position.y=-6.6;host.body.add(frame);const saved=host.body;let parts;host.body=frame;try{parts=addCadParts(host,data.filter(d=>d.role===sourceRole),{shell:materials.plastic(0x30332f,{roughness:.84})});}finally{host.body=saved;}host.timerCameraXAccessory={shape,sourceRole,frame,parts,nativeMesh:Object.values(parts)[0]};}
export class TwoEarMount extends Module{static meta={id:'m5stack.unit.timercamera-x.two-ear',name:'TimerCamera-X own static two-ear support',connector:spec.mount.connector};build(){build(this,'adapter','two-ear');}}
export class TwinHoleMount extends Module{static meta={id:'m5stack.unit.timercamera-x.twin-hole',name:'TimerCamera-X own static twin-hole support',connector:spec.mount.connector};build(){build(this,'clip','twin-hole');}}
